<?php require_once '../config/database.php';require_once '../includes/functions.php';require_admin();$id=(int)($_GET['id']??$_POST['id']??0);$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p)go('products.php');$pageTitle='Edit Product';$active='products';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$pr=(float)($_POST['price']??0);$im=trim($_POST['image']??'');$ca=trim($_POST['category']??'');$de=trim($_POST['description']??'');if($n&&$pr>0&&$im&&$ca&&$de){$s=$pdo->prepare('UPDATE products SET name=?,price=?,image=?,category=?,description=? WHERE id=?');$s->execute([$n,$pr,$im,$ca,$de,$id]);flash('success','Product updated successfully.');go('products.php');}else $err='Please fill all required fields.';}require 'header.php';?><div class="admin-top"><div><span class="eyebrow">Catalog</span><h1>Edit Product</h1><p>Update product information.</p></div></div><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><section class="admin-card"><form method="post"><input type="hidden" name="id" value="<?=$id?>"><div class="admin-form-grid"><div class="group"><label>Product Name</label><input class="input" name="name" value="<?=e($p['name'])?>" required></div><div class="group"><label>Price (₹)</label><input class="input" type="number" step="0.01" min="1" name="price" value="<?=e((string)$p['price'])?>" required></div><div class="group"><label>Category</label><input class="input" name="category" value="<?=e($p['category'])?>" required></div><div class="group"><label>Image URL</label><input class="input" name="image" value="<?=e($p['image'])?>" required></div></div><div class="group"><label>Description</label><textarea name="description" required><?=e($p['description'])?></textarea></div><button class="btn">Save Changes</button> <a class="btn secondary" href="products.php">Cancel</a></form></section><?php require 'footer.php';
